class BaseIncorrectStatus(Exception):
    pass


class IncorrectStatus(BaseIncorrectStatus):
    _re_pattern_class = type(re.compile(''))

    def __init__(self, param_name, expected_value, received_value):
        self.param_name = param_name
        self.expected_value = expected_value.pattern \
            if isinstance(expected_value, IncorrectStatus._re_pattern_class) else expected_value
        self.received_value = received_value
        message = "\n\tExpected '{}' is '{}', but received status is '{}'".format(
            self.param_name, self.expected_value, self.received_value)
        super(IncorrectStatus, self).__init__(message)


class IncorrectStatuses(BaseIncorrectStatus):
    def __init__(self, incorrect_statuses, device=None, additional_message=None):
        """
        :param incorrect_statuses:  list of IncorrectStatus
        :param device:              str, eg dist_name or any info related to device or its type
        :param additional_message:  str, additional info add at the beginning of exception
        """
        self.incorrect_statuses = incorrect_statuses
        self.device = device
        self.additional_message = additional_message
        self.message = "".join(map(str, incorrect_statuses))
        super(IncorrectStatuses, self).__init__(self.message)

    def __str__(self):
        message = "{}{}".format(self.additional_message, self.message) if self.additional_message else self.message
        return str(message)

    def __repr__(self):
        message = "{}:{}".format(self.device, self.message) if self.device else self.message
        return str(message)


class BaseIncorrectStatuses(BaseIncorrectStatus):
    def __init__(self, incorrect_statuses, additional_message=None):
        """
        :param incorrect_statuses:    list of IncorrectStatuses
        :param additional_message:          str, additional info add at the beginning of exception
        """
        self.incorrect_statuses = incorrect_statuses
        self.additional_message = additional_message
        self.message = "\n" + "\n\n".join(map(repr, incorrect_statuses))
        super(BaseIncorrectStatuses, self).__init__(self.message, additional_message)

    def __str__(self):
        message = "{}{}".format(self.additional_message, self.message) if self.additional_message else self.message
        return str(message)

    def __repr__(self):
        return str(self.message)


class IncorrectCellsStatuses(BaseIncorrectStatuses):
    def __init__(self, incorrect_cells_statuses, additional_message=None):
        super(IncorrectCellsStatuses, self).__init__(incorrect_statuses=incorrect_cells_statuses,
                                                     additional_message=additional_message)


